import { AfterViewInit, Component, DestroyRef, ElementRef, NgZone, inject, input, output, signal } from '@angular/core';
import { TablerIconComponent } from '@tabler/icons-angular';
import { HrmNavItem } from './hrm-side-nav';

/** hrm-top-nav — thanh điều hướng NGANG cấp sản phẩm (header app). Trái: logo/brand + [tnBrand];
 *  giữa: các mục điều hướng (≤5 mục luôn hiện); phải: vùng linh hoạt [tnActions] (tìm kiếm/nút/avatar).
 *  Mục chọn = pill nền nhạt. Nhiều đích/phân cấp → dùng Side Nav thay vì Top Nav.
 *  <hrm-top-nav [items]="nav" [selectedKey]="k" [logoSrc]="..."><input tnActions/><... tnActions/></hrm-top-nav> */
@Component({
  selector: 'hrm-top-nav',
  imports: [TablerIconComponent],
  template: `
    <header class="tn" [class.tn--center]="align() === 'center'"
      [class.tn--compact]="compact()" [class.tn--narrow]="narrow()"
      [attr.aria-label]="ariaLabel() || null">
      <div class="tn-brand">
        @if (logoSrc()) { <img class="tn-logo" [src]="logoSrc()" alt="logo" /> }
        <ng-content select="[tnBrand]" />
      </div>
      <!-- Menu inline (desktop) — ẩn khi compact, gom vào hamburger. -->
      <nav class="tn-items">
        <ng-content select="[tnNav]" />
        @for (it of items(); track it.key) {
          <button type="button" class="tn-item" [class.is-active]="it.key === selectedKey()"
            [disabled]="it.disabled ?? false" (click)="pick(it)">
            @if (it.icon) { <tabler-icon [icon]="$any(it.icon)" [size]="18" /> }
            <span>{{ it.label }}</span>
            @if (it.badge != null) { <span class="tn-badge">{{ it.badge }}</span> }
          </button>
        }
      </nav>
      <div class="tn-flex"><ng-content select="[tnActions]" /></div>
      <!-- Nút hamburger — chỉ HIỆN khi hẹp (compact). Mở drawer menu dọc. -->
      @if (compact() && items().length) {
        <button type="button" class="tn-burger" [class.is-open]="menuOpen()"
          [attr.aria-expanded]="menuOpen()" aria-haspopup="menu"
          [attr.aria-label]="menuLabel() || null" (click)="toggleMenu($event)">
          <span class="tn-burger-ic"></span>
        </button>
      }
      @if (compact() && menuOpen()) {
        <div class="tn-drawer" role="menu">
          @for (it of items(); track it.key) {
            <button type="button" class="tn-drawer-item" role="menuitem"
              [class.is-active]="it.key === selectedKey()"
              [disabled]="it.disabled ?? false" (click)="pick(it)">
              @if (it.icon) { <tabler-icon [icon]="$any(it.icon)" [size]="18" /> }
              <span>{{ it.label }}</span>
              @if (it.badge != null) { <span class="tn-badge">{{ it.badge }}</span> }
            </button>
          }
        </div>
      }
    </header>
  `,
  host: { class: 'hrm-top-nav', '(window:resize)': 'onResize()' },
  styles: [`
:host { display: block; }
.tn {
  position: relative;
  display: flex; align-items: center; gap: 16px; height: 56px; padding: 0 16px;
  background: var(--bg-surface); border-bottom: 1px solid var(--border-sub); font-family: var(--font-sans);
}
.tn-brand { display: flex; align-items: center; gap: 8px; flex: none; }
.tn-logo { height: 28px; width: auto; }
/* Menu điều hướng — cuộn NGANG khi hẹp (không tràn/đè vùng actions bên phải).
   Ẩn thanh cuộn cho gọn; items giữ nowrap và cuộn thay vì rớt/đè. */
.tn-items {
  display: flex; align-items: center; gap: 2px; flex: 1 1 auto; min-width: 0;
  overflow-x: auto; overflow-y: hidden;
  scrollbar-width: none; -ms-overflow-style: none;
}
.tn-items::-webkit-scrollbar { display: none; }
.tn-item { flex: none; }
.tn--center .tn-items { justify-content: center; }
.tn-item {
  display: inline-flex; align-items: center; gap: 6px; padding: 7px 12px;
  border: 0; background: transparent; border-radius: var(--radius-lg); cursor: pointer;
  font-size: var(--fs-14); font-weight: 400; color: var(--text-body); font-family: inherit; white-space: nowrap;
  transition: background var(--duration-fast, .15s) var(--ease-out, ease), color var(--duration-fast, .15s) var(--ease-out, ease);
}
.tn-item:hover:not(:disabled) { background: var(--bg-surface-subtle); color: var(--text-strong); }
.tn-item:disabled { color: var(--text-disabled); cursor: not-allowed; }
.tn-item.is-active { background: var(--primary-bg-subtle); color: var(--primary-base); font-weight: 500; }
:host-context(.dark) .tn-item.is-active { color: var(--text-strong); }
.tn-badge {
  font-size: var(--fs-11); font-weight: 600; line-height: 1; padding: 3px 7px; border-radius: var(--radius-full);
  background: var(--primary-bg-soft); color: var(--primary-base);
}
.tn-flex { display: flex; align-items: center; gap: 8px; flex: 0 1 auto; min-width: 0; margin-left: auto; }

/* Hamburger — icon 3 gạch bằng CSS (không phụ thuộc icon lib), mở/đóng thành X. */
.tn-burger {
  flex: none; place-items: center; width: 36px; height: 36px; margin-left: 4px;
  border: 1px solid var(--border-sub); background: var(--bg-surface); border-radius: var(--radius-md);
  cursor: pointer; color: var(--text-body);
}
.tn-burger:hover { border-color: var(--primary-base); color: var(--text-strong); }
.tn-burger:focus-visible { outline: 2px solid var(--primary-focus-ring, var(--primary-base)); outline-offset: 1px; }
.tn-burger-ic, .tn-burger-ic::before, .tn-burger-ic::after {
  content: ''; display: block; width: 18px; height: 2px; border-radius: var(--radius-full);
  background: currentColor; transition: transform var(--duration-fast, .15s) var(--ease-out, ease), opacity var(--duration-fast, .15s) var(--ease-out, ease);
}
.tn-burger-ic { position: relative; }
.tn-burger-ic::before { position: absolute; top: -6px; left: 0; }
.tn-burger-ic::after  { position: absolute; top: 6px; left: 0; }
.tn-burger.is-open .tn-burger-ic { background: transparent; }
.tn-burger.is-open .tn-burger-ic::before { transform: translateY(6px) rotate(45deg); }
.tn-burger.is-open .tn-burger-ic::after  { transform: translateY(-6px) rotate(-45deg); }

/* Drawer menu dọc — panel dưới header khi compact. */
.tn-drawer {
  position: absolute; top: 100%; left: 8px; right: 8px; z-index: 40; margin-top: 6px;
  flex-direction: column; gap: 2px; padding: 6px;
  background: var(--bg-surface); border: 1px solid var(--border-sub);
  border-radius: var(--radius-xl); box-shadow: var(--shadow-regular-md);
}
.tn-drawer-item {
  display: flex; align-items: center; gap: 10px; width: 100%; padding: 10px 12px;
  border: 0; background: transparent; border-radius: var(--radius-md); cursor: pointer;
  font-size: var(--fs-14); color: var(--text-body); font-family: inherit; text-align: left;
}
.tn-drawer-item:hover:not(:disabled) { background: var(--bg-surface-subtle); color: var(--text-strong); }
.tn-drawer-item:disabled { color: var(--text-disabled); cursor: not-allowed; }
.tn-drawer-item.is-active { background: var(--primary-bg-subtle); color: var(--primary-base); font-weight: 500; }
.tn-drawer-item .tn-badge { margin-left: auto; }

/* ── Responsive (class .tn--compact do JS bật khi bề rộng nav < 820px — ResizeObserver
   đo bề rộng THỰC của top-nav, không viewport). Mặc định rộng: menu inline. ── */
.tn-burger, .tn-drawer { display: none; }
.tn--compact .tn-items { display: none; }
.tn--compact .tn-burger { display: grid; }
.tn--compact .tn-drawer { display: flex; }
  `],
})
export class HrmTopNav implements AfterViewInit {
  private readonly host = inject(ElementRef).nativeElement as HTMLElement;
  readonly items = input<HrmNavItem[]>([]);
  readonly selectedKey = input<string>('');
  /** Canh mục điều hướng: 'start' (mặc định) hoặc 'center' (giữa, logo trái · actions phải). */
  readonly align = input<'start' | 'center'>('start');
  /** Logo đầy đủ (URL) hiện bên trái. Có thể thay bằng slot [tnBrand]. */
  readonly logoSrc = input('');
  readonly ariaLabel = input('');
  /** Nhãn a11y nút hamburger (i18n, bên gọi cấp). */
  readonly menuLabel = input('');
  /** Bề rộng (px) mà DƯỚI đó gom menu vào hamburger. */
  readonly mobileBreakpoint = input(820);
  /** Bề rộng (px) mà DƯỚI đó bật class .tn--narrow — mốc HẸP HƠN để app thu gọn nội dung
   *  trong [tnActions] (VD ô tìm kiếm → icon) CHỈ khi thật sự không đủ chỗ. Độc lập ngưỡng hamburger. */
  readonly narrowBreakpoint = input(400);
  readonly itemClick = output<HrmNavItem>();

  /** Chế độ hẹp (menu → hamburger) — theo bề rộng THỰC của header (ResizeObserver, KHÔNG
   *  dùng container-type vì containment làm sập layout ancestor content-sized). */
  protected readonly compact = signal(false);
  /** Rất hẹp — app dùng .tn--narrow để thu ô tìm kiếm/nội dung actions thành icon. */
  protected readonly narrow = signal(false);
  /** Drawer menu (compact) đang mở. */
  protected readonly menuOpen = signal(false);

  /** Đo lại theo bề rộng THỰC của header → bật compact (<820, menu→hamburger) + narrow
   *  (<400, app thu search→icon). Gọi ở: ngAfterViewInit (initial), window:resize, ResizeObserver
   *  (đổi container không do window — VD gập side nav). offsetWidth luôn cho width thật (khác
   *  container-type từng làm sập layout). */
  protected measure(): void {
    const w = this.host.offsetWidth;
    if (w <= 0) return;   // host ẩn (tab khác) → giữ nguyên
    this.compact.set(w < this.mobileBreakpoint());
    this.narrow.set(w < this.narrowBreakpoint());
    if (w >= this.mobileBreakpoint()) this.menuOpen.set(false);
  }
  protected onResize(): void { this.measure(); }

  ngAfterViewInit(): void { this.measure(); }

  constructor() {
    const host = this.host;
    const zone = inject(NgZone);
    // ResizeObserver cho thay đổi bề rộng CONTAINER (không phải viewport) — gập side nav…
    if (typeof ResizeObserver !== 'undefined') {
      const ro = new ResizeObserver(() => zone.run(() => this.measure()));
      ro.observe(host);
      inject(DestroyRef).onDestroy(() => ro.disconnect());
    }
    // Click ra ngoài → đóng drawer.
    const onDoc = (e: Event) => {
      if (this.menuOpen() && !host.contains(e.target as Node)) this.menuOpen.set(false);
    };
    document.addEventListener('click', onDoc, true);
    inject(DestroyRef).onDestroy(() => document.removeEventListener('click', onDoc, true));
  }

  protected toggleMenu(e: Event): void {
    e.stopPropagation();   // tránh onDoc đóng ngay
    this.menuOpen.update((v) => !v);
  }

  protected pick(it: HrmNavItem): void {
    if (it.disabled) return;
    this.menuOpen.set(false);   // chọn xong đóng drawer
    this.itemClick.emit(it);
  }
}
